import{_ as t,o as i,c as o,ak as s,aw as a,ax as n,ay as l,az as r}from"./chunks/framework.CwE7b36_.js";const f=JSON.parse('{"title":"Outils de programmation de scripts avec Unity","description":"","frontmatter":{},"headers":[],"relativePath":"02_InstallationIDE_Scripts.md","filePath":"02_InstallationIDE_Scripts.md","lastUpdated":1769019243000}'),d={name:"02_InstallationIDE_Scripts.md"};function u(c,e,p,m,g,v){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="outils-de-programmation-de-scripts-avec-unity" tabindex="-1">Outils de programmation de scripts avec Unity <a class="header-anchor" href="#outils-de-programmation-de-scripts-avec-unity" aria-label="Permalink to “Outils de programmation de scripts avec Unity”">​</a></h1><p>Les scripts dans Unity sont principalement écrits en C#. Pour les éditer, on utilise des éditeurs externels. Les deux options gratuites les plus utilisées sont <strong>Visual Studio</strong> et <strong>VS Code</strong> parce qu&#39;elles ont une bonne intégration avec Unity pour la gestion de code et le débogage.</p><h2 id="integration-avec-vscode-ou-visual-studio" tabindex="-1">Intégration avec VSCode ou Visual Studio <a class="header-anchor" href="#integration-avec-vscode-ou-visual-studio" aria-label="Permalink to “Intégration avec VSCode ou Visual Studio”">​</a></h2><p>Unity s&#39;intègre parfaitement avec des éditeurs de code externes tels que Visual Studio Code (VSCode) (logo bleu) ou Visual Studio Community (logo violet). <img src="'+a+'" alt="Logo VS Code"><img src="'+n+'" alt="Logo Visual Studio"></p><h3 id="vscode-ou-visual-studio-community" tabindex="-1">VSCode ou Visual Studio Community ? <a class="header-anchor" href="#vscode-ou-visual-studio-community" aria-label="Permalink to “VSCode ou Visual Studio Community ?”">​</a></h3><p>Visual Studio Code est un éditeur de code léger et polyvalent, tandis que Visual Studio Community est un environnement de développement intégré (IDE) plus complet. Les deux offrent d&#39;excellentes fonctionnalités pour le développement en C# avec Unity, telles que la complétion de code, le débogage, et la gestion des projets. Le deux sont gratuits et largement utilisés dans la communauté Unity mais VSCode est plus léger et plus rapide à lancer.</p><p>Voici comment configurer Unity pour utiliser l&#39;un de ces éditeurs :</p><ol><li>Ouvrir Unity et aller dans <code>Edit</code> &gt; <code>Preferences</code> (Windows) ou <code>Unity</code> &gt; <code>Preferences</code> (macOS).</li><li>Dans la section <code>External Tools</code>, sélectionner <code>Visual Studio Code</code> ou <code>Visual Studio</code> dans le menu déroulant <code>External Script Editor</code>.</li><li>Assurez-vous que les options <code>Generate all .csproj files</code> et <code>Generate .csproj files for:</code> sont cochées pour inclure les fichiers de projet nécessaires.</li></ol><h3 id="installation-de-visual-studio-community" tabindex="-1">Installation de Visual Studio Community <a class="header-anchor" href="#installation-de-visual-studio-community" aria-label="Permalink to “Installation de Visual Studio Community”">​</a></h3><p>Si vous choisissez d&#39;utiliser Visual Studio Community, voici comment l&#39;installer :</p><ol><li>Rendez-vous sur le site officiel de Visual Studio : <a href="https://visualstudio.microsoft.com/fr/downloads/" target="_blank" rel="noreferrer">https://visualstudio.microsoft.com/fr/downloads/</a></li><li>Téléchargez l&#39;installateur de Visual Studio Community.</li><li>Lancez l&#39;installateur et sélectionnez les charges de travail suivantes : <ul><li><strong>Développement de jeux avec Unity</strong> : Cela installera les outils nécessaires pour le développement Unity.</li></ul></li><li>Suivez les instructions à l&#39;écran pour terminer l&#39;installation.</li><li>Une fois l&#39;installation terminée, redémarrez Unity pour que les modifications prennent effet.</li></ol><h3 id="installation-des-extensions-pour-vscode" tabindex="-1">Installation des extensions pour VSCode <a class="header-anchor" href="#installation-des-extensions-pour-vscode" aria-label="Permalink to “Installation des extensions pour VSCode”">​</a></h3><p>Dans VSCode, il est recommandé d&#39;installer l&#39;extension <code>C# for Visual Studio Code</code> pour une meilleure prise en charge de C# et de Unity. Cela inclut la complétion de code, le débogage, et d&#39;autres fonctionnalités utiles et le package <code>Unity Tools</code> pour des fonctionnalités supplémentaires spécifiques à Unity.</p><p>Vous devez également installer le SDK .NET si ce n&#39;est pas déjà fait, car il est nécessaire pour le développement en C# avec VSCode. <a href="https://dotnet.microsoft.com/en-us/download" target="_blank" rel="noreferrer">SDK .NET</a></p><p><img src="'+l+'" alt="extension C#"><img src="'+r+'" alt="extension Unity Tools"></p>',15)])])}const _=t(d,[["render",u]]);export{f as __pageData,_ as default};
